const express = require('express');
const multer = require('multer');
const AWS = require('aws-sdk');
const bcrypt = require('bcrypt');
const mysql = require('mysql2/promise');
require('dotenv').config();

const router = express.Router();

// Configure AWS S3
const s3 = new AWS.S3({
  accessKeyId: process.env.AWS_ACCESS_KEY_ID,
  secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  region: process.env.AWS_REGION
});

// Configure multer for file uploads
const upload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: 5 * 1024 * 1024 // 5MB limit per file
  }
});

// MySQL connection pool
const pool = mysql.createPool({
  host: process.env.DB_HOST,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
  waitForConnections: true,
  connectionLimit: 10,
  queueLimit: 0
});

// Admin authentication middleware
async function authenticateAdmin(password) {
  const adminPasswordHash = process.env.ADMIN_PASSWORD_HASH;
  if (!adminPasswordHash) {
    throw new Error('Admin credentials not configured');
  }
  return bcrypt.compare(password, adminPasswordHash);
}

// Upload image to S3
async function uploadToS3(file, key) {
  const params = {
    Bucket: process.env.AWS_S3_BUCKET,
    Key: key,
    Body: file.buffer,
    ContentType: 'image/jpeg',
    ACL: 'public-read'
  };

  return s3.upload(params).promise();
}

// Route handler
router.post('/upload-images', 
  upload.fields([{ name: 'hdImage', maxCount: 1 }, { name: 'compressedImage', maxCount: 1 }]),
  async (req, res) => {
    try {
      // 1. Admin Authentication
      const { adminPassword, title } = req.body;
      if (!adminPassword) {
        return res.status(401).json({ error: 'Admin password required' });
      }

      const isAuthenticated = await authenticateAdmin(adminPassword);
      if (!isAuthenticated) {
        return res.status(403).json({ error: 'Invalid admin credentials' });
      }

      // 2. Validate file uploads
      if (!req.files || !req.files.hdImage || !req.files.compressedImage) {
        return res.status(400).json({ error: 'Both HD and compressed images are required' });
      }

      const hdImage = req.files.hdImage[0];
      const compressedImage = req.files.compressedImage[0];

      // Validate file types
      if (!hdImage.mimetype.startsWith('image/') || !compressedImage.mimetype.startsWith('image/')) {
        return res.status(400).json({ error: 'Uploaded files must be images' });
      }

      // 3. Upload to S3
      const timestamp = Date.now();
      const hdKey = `images/hd/${timestamp}-${hdImage.originalname}`;
      const compressedKey = `images/compressed/${timestamp}-${compressedImage.originalname}`;

      const [hdUploadResult, compressedUploadResult] = await Promise.all([
        uploadToS3(hdImage, hdKey),
        uploadToS3(compressedImage, compressedKey)
      ]);

      // 4. Store metadata in MySQL
      const connection = await pool.getConnection();
      try {
        await connection.execute(
          'INSERT INTO images (title, hd_url, compressed_url, created_at) VALUES (?, ?, ?, NOW())',
          [title, hdUploadResult.Location, compressedUploadResult.Location]
        );

        res.status(201).json({ 
          message: 'Images uploaded successfully',
          hdUrl: hdUploadResult.Location,
          compressedUrl: compressedUploadResult.Location
        });
      } catch (dbError) {
        console.error('Database error:', dbError);
        res.status(500).json({ error: 'Failed to store image metadata' });
      } finally {
        connection.release();
      }

    } catch (error) {
      console.error('Error in upload route:', error);

      if (error.code === 'LIMIT_FILE_SIZE') {
        return res.status(413).json({ error: 'File size exceeds 5MB limit' });
      }

      res.status(500).json({ 
        error: 'Internal server error',
        details: error.message 
      });
    }
  }
);

module.exports = router;
```

### Key Features:

1. **Admin Authentication**:
   - Uses bcrypt to compare provided password with hashed password from env vars
   - Returns 401 for missing password and 403 for incorrect password

2. **File Upload Handling**:
   - Uses multer for handling multipart form data
   - Validates that both HD and compressed images are provided
   - Enforces 5MB file size limit
   - Validates file types are images

3. **S3 Uploads**:
   - Uploads files with public-read ACL and image/jpeg content type
   - Uses Promise.all for parallel uploads
   - Organizes files in different S3 prefixes (hd/ and compressed/)

4. **MySQL Storage**:
   - Uses connection pooling for efficient database connections
   - Stores title, URLs, and timestamp
   - Properly releases connections back to the pool

5. **Error Handling**:
   - Specific status codes for different error cases
   - Proper error messages without exposing sensitive info
   - Database connection cleanup with finally block

